export interface StoreOptions {
  now?: () => Date
  newId?: () => string
}

interface ProjectRow {
  id: string
  name: string
  data: string
  view: string | null
  revision: number
  created_at: string
  updated_at: string
}

interface DraftRow {
  id: string
  project_id: string
  label: string
  data: string
  base_revision: number
  base_data: string
  revision: number
  part_revisions: string
  last_changed_by: Author
  human_viewed_revision: number
  state: DraftState
  created_at: string
  updated_at: string
  ended_at: string | null
}

interface SnapshotRow {
  id: number
  label: string
  kind: SnapshotKind
  created_at: string
}

// Decodes any input into the current document shape and enforces the size cap.
function encodeData(input: unknown): string {
  const json = JSON.stringify(decodeProjectData(input))
  if (json.length > MAX_DATA_CHARS) throw new Error('Projekt je príliš veľký')
  return json
}

const parseJson = (json: string | null): unknown => {
  if (json === null) return undefined
  try {
    return JSON.parse(json)
  } catch {
    return undefined
  }
}

function requiredText(value: string, field: string, max: number) {
  const s = limitText(value, max)
  if (!s) throw new Error(`${field}: nesmie byť prázdny`)
  return s
}

const toRecord = (row: ProjectRow): ProjectRecord => ({
  id: row.id,
  name: row.name,
  data: decodeProjectData(parseJson(row.data)),
  view: row.view === null ? defaultProjectView() : decodeProjectView(parseJson(row.view)),
  revision: row.revision,
  createdAt: row.created_at,
  updatedAt: row.updated_at,
})

// A draft's (or a draft snapshot's) parts are stored as a decoded document whose other fields are defaults.
const encodeParts = (parts: Parts) => encodeData(writeParts(defaultProjectData(), parts))
const decodeParts = (json: string) => readParts(decodeProjectData(parseJson(json)))

function decodePartRevisions(json: string): Record<PartName, number> {
  const raw = (parseJson(json) ?? {}) as Partial<Record<PartName, unknown>>
  return Object.fromEntries(PARTS.map((part) => [part, typeof raw[part] === 'number' ? raw[part] : 1])) as Record<PartName, number>
}

const toDraftSummary = (row: DraftRow): DraftSummary => ({
  id: row.id,
  projectId: row.project_id,
  label: row.label,
  state: row.state,
  revision: row.revision,
  partRevisions: decodePartRevisions(row.part_revisions),
  lastChangedBy: row.last_changed_by,
  humanViewedRevision: row.human_viewed_revision,
  base: { projectRevision: row.base_revision },
  createdAt: row.created_at,
  updatedAt: row.updated_at,
  endedAt: row.ended_at,
})

const toDraft = (row: DraftRow): DraftRecord => ({
  ...toDraftSummary(row),
  parts: decodeParts(row.data),
  base: { projectRevision: row.base_revision, parts: decodeParts(row.base_data) },
})

const toSnapshot = (row: SnapshotRow): SnapshotSummary => ({
  id: row.id,
  label: row.label,
  kind: row.kind,
  auto: row.kind === 'auto',
  createdAt: row.created_at,
})

export function createProjectStore(db: DatabaseSync, options: StoreOptions = {}): ProjectStore {
  const clock = options.now ?? (() => new Date())
  const now = () => clock().toISOString()
  const newId = options.newId ?? (() => randomBytes(8).toString('base64url'))
  const tx = <T>(fn: () => T) => transaction(db, fn)

  const findRow = (id: string) => db.prepare('SELECT * FROM projects WHERE id = ?').get(id) as ProjectRow | undefined
  const getProject = (id: string) => {
    const row = findRow(id)
    return row ? toRecord(row) : null
  }

  function insertProject(name: string, json: string, view: string | null): ProjectRecord {
    const id = newId()
    const ts = now()
    db.prepare('INSERT INTO projects (id, name, data, view, revision, created_at, updated_at) VALUES (?, ?, ?, ?, 1, ?, ?)').run(
      id,
      requiredText(name, 'Názov', PROJECT_NAME_MAX),
      json,
      view,
      ts,
      ts,
    )
    return getProject(id)!
  }

  // Inserts a snapshot of a project (draftId null) or of one of its drafts and prunes older snapshots of the same
  // kind in the same history (named and final snapshots are never pruned).
  function insertSnapshot(projectId: string, label: string, data: string, kind: SnapshotKind, draftId: string | null = null) {
    const info = db
      .prepare('INSERT INTO snapshots (project_id, draft_id, label, kind, data, created_at) VALUES (?, ?, ?, ?, ?, ?)')
      .run(projectId, draftId, requiredText(label, 'Popis', LABEL_MAX), kind, data, now())
    const kept = KEPT[kind]
    if (kept !== undefined) {
      db.prepare(
        `DELETE FROM snapshots WHERE project_id = ? AND draft_id IS ? AND kind = ? AND id NOT IN
           (SELECT id FROM snapshots WHERE project_id = ? AND draft_id IS ? AND kind = ? ORDER BY id DESC LIMIT ?)`,
      ).run(projectId, draftId, kind, projectId, draftId, kind, kept)
    }
    return Number(info.lastInsertRowid)
  }

  // Auto snapshot policy (projects and drafts alike): back up the state being replaced at most every 20 minutes.
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Ended drafts in history"
  // Changes: Fork a draft from the project's current state (shared by createDraft and restore from an ended draft);
  //          `parts` replaces the forked parts when given. Runs inside the caller's transaction.
  function insertDraft(projectId: string, label: string, author: Author, parts?: Parts): DraftRecord | null {
    const name = requiredText(label, 'Popis', LABEL_MAX)
    const project = findRow(projectId)
    if (!project) return null
    const base = encodeParts(readParts(decodeProjectData(parseJson(project.data))))
    const data = parts ? encodeParts(parts) : base
    const revisions = JSON.stringify(Object.fromEntries(PARTS.map((part) => [part, 1])))
    const id = newId()
    const ts = now()
    db.prepare(
      `INSERT INTO drafts (id, project_id, label, data, base_revision, base_data, revision, part_revisions,
         last_changed_by, human_viewed_revision, state, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, 1, ?, ?, ?, 'open', ?, ?)`,
    ).run(id, projectId, name, data, project.revision, base, revisions, author, author === 'human' ? 1 : 0, ts, ts)
    return getDraft(id)
  }

  function autoSnapshot(projectId: string, data: string, draftId: string | null = null) {
    const lastAuto = db
      .prepare("SELECT created_at FROM snapshots WHERE project_id = ? AND draft_id IS ? AND kind = 'auto' ORDER BY id DESC LIMIT 1")
      .get(projectId, draftId) as { created_at: string } | undefined
    if (!lastAuto || clock().getTime() - Date.parse(lastAuto.created_at) >= AUTO_SNAPSHOT_EVERY_MS) {
      insertSnapshot(projectId, 'Automatická záloha', data, 'auto', draftId)
    }
  }

  // Overwrites the document, keeping the previous state as a safety snapshot.
  function replaceData(row: ProjectRow, json: string, label: string) {
    insertSnapshot(row.id, label, row.data, 'safety')
    db.prepare('UPDATE projects SET data = ?, revision = revision + 1, updated_at = ? WHERE id = ?').run(json, now(), row.id)
    return getProject(row.id)
  }

  const listSnapshots = (projectId: string) =>
    (
      db
        .prepare('SELECT id, label, kind, created_at FROM snapshots WHERE project_id = ? AND draft_id IS NULL ORDER BY id DESC')
        .all(projectId) as unknown as SnapshotRow[]
    ).map(toSnapshot)

  const findDraftRow = (id: string) => db.prepare('SELECT * FROM drafts WHERE id = ?').get(id) as DraftRow | undefined
  const getDraft = (id: string) => {
    const row = findDraftRow(id)
    return row ? toDraft(row) : null
  }

  return {
    listProjects() {
      const rows = db
        .prepare(
          `SELECT p.*, (SELECT COUNT(*) FROM snapshots s WHERE s.project_id = p.id AND s.draft_id IS NULL) AS snapshot_count,
             (SELECT COUNT(*) FROM drafts d WHERE d.project_id = p.id AND d.state = 'open') AS open_drafts
           FROM projects p ORDER BY p.updated_at DESC`,
        )
        .all() as unknown as (ProjectRow & { snapshot_count: number; open_drafts: number })[]
      return rows.map((row) => {
        const data = decodeProjectData(parseJson(row.data))
        return {
          id: row.id,
          name: row.name,
          revision: row.revision,
          createdAt: row.created_at,
          updatedAt: row.updated_at,
          llRules: parseGrammar(data.ll.grammar).rules.length,
          // AI generated by: Claude Code / claude-opus-5-5
          // Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
          // Changes: Table size (with $) from the precedence-table module.
          precSize: precTableSize(data.prec),
          snapshots: row.snapshot_count,
          openDrafts: row.open_drafts,
        }
      })
    },

    getProject,

    createProject: (name, data) => insertProject(name, encodeData(data), null),

    saveProject(id, data, baseRevision) {
      const json = encodeData(data)
      return tx((): SaveResult => {
        const row = findRow(id)
        if (!row) return { status: 'missing' }
        if (row.revision !== baseRevision) return { status: 'conflict', project: toRecord(row) }
        if (json === row.data) return { status: 'saved', revision: row.revision, updatedAt: row.updated_at }

        autoSnapshot(id, row.data)

        const ts = now()
        db.prepare('UPDATE projects SET data = ?, revision = revision + 1, updated_at = ? WHERE id = ?').run(json, ts, id)
        return { status: 'saved', revision: row.revision + 1, updatedAt: ts }
      })
    },

    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Human edits drafts"
    // Changes: Settings only, over whatever parts the project has now (no whole-document check: they are not parts,
    //          so nothing the draft view shows of the project's parts can be overwritten); same auto snapshot policy.
    saveProjectSettings(id, settings) {
      return tx(() => {
        const row = findRow(id)
        if (!row) return { status: 'missing' as const }
        const json = encodeData(writeSettings(decodeProjectData(parseJson(row.data)), settings))
        if (json === row.data) return { status: 'saved' as const, revision: row.revision, updatedAt: row.updated_at }
        autoSnapshot(id, row.data)
        const ts = now()
        db.prepare('UPDATE projects SET data = ?, revision = revision + 1, updated_at = ? WHERE id = ?').run(json, ts, id)
        return { status: 'saved' as const, revision: row.revision + 1, updatedAt: ts }
      })
    },

    saveViewState(id, view) {
      const decoded = decodeProjectView(view)
      const info = db.prepare('UPDATE projects SET view = ? WHERE id = ?').run(JSON.stringify(decoded), id)
      return info.changes ? decoded : null
    },

    replaceProjectData(id, data, label) {
      const json = encodeData(data)
      return tx(() => {
        const row = findRow(id)
        return row ? replaceData(row, json, label) : null
      })
    },

    renameProject(id, name) {
      db.prepare('UPDATE projects SET name = ? WHERE id = ?').run(requiredText(name, 'Názov', PROJECT_NAME_MAX), id)
      return getProject(id)
    },

    deleteProject(id) {
      db.prepare('DELETE FROM projects WHERE id = ?').run(id)
    },

    duplicateProject(id) {
      const row = findRow(id)
      if (!row) return null
      const name = `${limitText(row.name, PROJECT_NAME_MAX - ' (kópia)'.length)} (kópia)`
      return insertProject(name, encodeData(parseJson(row.data)), row.view)
    },

    listSnapshots,

    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Agents read projects over MCP"
    // Changes: Snapshot ids are unique across projects, so the id alone finds the snapshot and its project.
    getSnapshot(snapshotId) {
      const row = db
        .prepare('SELECT id, project_id, draft_id, label, kind, data, created_at FROM snapshots WHERE id = ?')
        .get(snapshotId) as (SnapshotRow & { project_id: string; draft_id: string | null; data: string }) | undefined
      return row
        ? { ...toSnapshot(row), projectId: row.project_id, draftId: row.draft_id, data: decodeProjectData(parseJson(row.data)) }
        : null
    },

    createSnapshot(projectId, label) {
      return tx(() => {
        const row = findRow(projectId)
        if (!row) return null
        const id = insertSnapshot(projectId, label, row.data, 'named')
        return listSnapshots(projectId).find((s) => s.id === id) ?? null
      })
    },

    restoreSnapshot(projectId, snapshotId) {
      return tx(() => {
        const snap = db.prepare('SELECT label, data FROM snapshots WHERE id = ? AND project_id = ? AND draft_id IS NULL').get(snapshotId, projectId) as
          | { label: string; data: string }
          | undefined
        const row = findRow(projectId)
        if (!snap || !row) return null
        return replaceData(row, encodeData(parseJson(snap.data)), `Pred obnovením „${snap.label}“`)
      })
    },

    deleteSnapshot(projectId, snapshotId) {
      return db.prepare('DELETE FROM snapshots WHERE id = ? AND project_id = ? AND draft_id IS NULL').run(snapshotId, projectId).changes > 0
    },

    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Agents create, edit and discard drafts"
    // Changes: Draft lifecycle – create (fork), read, list, relabel, edit with per-part revisions, discard.
    createDraft(projectId, label, author) {
      return tx(() => insertDraft(projectId, label, author))
    },

    getDraft,

    listDrafts(projectId) {
      const rows = db
        .prepare("SELECT * FROM drafts WHERE project_id = ? ORDER BY state = 'open' DESC, updated_at DESC, rowid DESC")
        .all(projectId) as unknown as DraftRow[]
      return rows.map(toDraftSummary)
    },

    relabelDraft(draftId, label) {
      const name = requiredText(label, 'Popis', LABEL_MAX)
      return tx((): DraftChangeResult => {
        const row = findDraftRow(draftId)
        if (!row) return { status: 'missing' }
        if (row.state !== 'open') return { status: 'ended', draft: toDraft(row) }
        if (name !== row.label) db.prepare('UPDATE drafts SET label = ?, updated_at = ? WHERE id = ?').run(name, now(), draftId)
        return { status: 'saved', draft: getDraft(draftId)! }
      })
    },

    editDraft(draftId, edit, { author, baseRevision }) {
      return tx((): DraftEditResult => {
        const row = findDraftRow(draftId)
        if (!row) return { status: 'missing' }
        const draft = toDraft(row)
        if (draft.state !== 'open') return { status: 'ended', draft }

        const change = typeof edit === 'function' ? edit(draft.parts) : edit
        const current = writeParts(defaultProjectData(), draft.parts)
        const json = encodeParts(readParts(writeParts(current, change)))
        const next = decodeProjectData(parseJson(json))
        const touched = PARTS.filter((part) => change[part] !== undefined && !partEquals(part, current, next))

        // Per part: a stale base revision only matters for parts someone else changed since then.
        if (baseRevision !== undefined && baseRevision < draft.revision) {
          const overlap = touched.filter((part) => draft.partRevisions[part] > baseRevision)
          if (overlap.length) return { status: 'conflict', draft, parts: overlap }
        }
        if (!touched.length) return { status: 'saved', draft, changed: [] }

        autoSnapshot(draft.projectId, row.data, draftId)
        const revision = draft.revision + 1
        const partRevisions = { ...draft.partRevisions }
        for (const part of touched) partRevisions[part] = revision
        db.prepare(
          `UPDATE drafts SET data = ?, revision = ?, part_revisions = ?, last_changed_by = ?,
             human_viewed_revision = CASE WHEN ? = 'human' THEN ? ELSE human_viewed_revision END, updated_at = ?
           WHERE id = ?`,
        ).run(json, revision, JSON.stringify(partRevisions), author, author, revision, now(), draftId)
        return { status: 'saved', draft: getDraft(draftId)!, changed: touched }
      })
    },

    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Adopt and discard in the editor"
    // Changes: Adopt chosen parts (export naming and simulation inputs are never touched).
    adoptDraft(draftId, parts, projectRevision) {
      const chosen = PARTS.filter((part) => parts.includes(part))
      if (!chosen.length) throw new Error('Vyber aspoň jednu časť na prevzatie')
      return tx((): AdoptResult => {
        const row = findDraftRow(draftId)
        if (!row) return { status: 'missing' }
        const draft = toDraft(row)
        if (draft.state !== 'open') return { status: 'ended', draft }
        const project = findRow(row.project_id)!
        if (project.revision !== projectRevision) return { status: 'stale', project: toRecord(project), draft }

        const adopted = Object.fromEntries(chosen.map((part) => [part, draft.parts[part]])) as Partial<Parts>
        const json = encodeData(writeParts(decodeProjectData(parseJson(project.data)), adopted))
        replaceData(project, json, `Pred prevzatím návrhu „${row.label}“`)
        insertSnapshot(row.project_id, `Prevzatý návrh „${row.label}“`, row.data, 'final', draftId)
        const ts = now()
        db.prepare("UPDATE drafts SET state = 'adopted', ended_at = ?, updated_at = ? WHERE id = ?").run(ts, ts, draftId)
        return { status: 'adopted', project: getProject(row.project_id)!, draft: getDraft(draftId)! }
      })
    },

    discardDraft(draftId) {
      return tx((): DraftChangeResult => {
        const row = findDraftRow(draftId)
        if (!row) return { status: 'missing' }
        if (row.state !== 'open') return { status: 'ended', draft: toDraft(row) }
        insertSnapshot(row.project_id, `Zahodený návrh „${row.label}“`, row.data, 'final', draftId)
        const ts = now()
        db.prepare("UPDATE drafts SET state = 'discarded', ended_at = ?, updated_at = ? WHERE id = ?").run(ts, ts, draftId)
        return { status: 'saved', draft: getDraft(draftId)! }
      })
    },

    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Human sees and opens drafts"
    // Changes: Record the revision the human saw (clamped to the draft's revision, never lowered); no updated_at bump.
    markDraftViewed(draftId, revision) {
      return tx((): DraftChangeResult => {
        const row = findDraftRow(draftId)
        if (!row) return { status: 'missing' }
        if (row.state !== 'open') return { status: 'ended', draft: toDraft(row) }
        const seen = Math.max(row.human_viewed_revision, Math.min(revision, row.revision))
        if (seen !== row.human_viewed_revision) db.prepare('UPDATE drafts SET human_viewed_revision = ? WHERE id = ?').run(seen, draftId)
        return { status: 'saved', draft: getDraft(draftId)! }
      })
    },

    listDraftSnapshots(draftId) {
      return (
        db
          .prepare('SELECT id, label, kind, created_at FROM snapshots WHERE draft_id = ? ORDER BY id DESC')
          .all(draftId) as unknown as SnapshotRow[]
      ).map(toSnapshot)
    },

    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Draft history"
    // Changes: Named snapshot of an open draft (never pruned).
    createDraftSnapshot(draftId, label) {
      return tx((): DraftSnapshotResult => {
        const row = findDraftRow(draftId)
        if (!row) return { status: 'missing' }
        if (row.state !== 'open') return { status: 'ended', draft: toDraft(row) }
        const id = insertSnapshot(row.project_id, label, row.data, 'named', draftId)
        const snap = db.prepare('SELECT id, label, kind, created_at FROM snapshots WHERE id = ?').get(id) as unknown as SnapshotRow
        return { status: 'saved', snapshot: toSnapshot(snap) }
      })
    },

    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Draft history"
    // Changes: Restore one of the draft's own snapshots into the open draft: safety snapshot of the current state
    //          first (last 10 kept per draft), then a human change of the parts that differ. The project is untouched.
    restoreDraftSnapshot(draftId, snapshotId) {
      return tx((): DraftChangeResult => {
        const row = findDraftRow(draftId)
        const snap = db.prepare('SELECT label, data FROM snapshots WHERE id = ? AND draft_id = ?').get(snapshotId, draftId) as
          | { label: string; data: string }
          | undefined
        if (!row || !snap) return { status: 'missing' }
        const draft = toDraft(row)
        if (draft.state !== 'open') return { status: 'ended', draft }

        insertSnapshot(row.project_id, `Pred obnovením „${snap.label}“`, row.data, 'safety', draftId)
        const json = encodeParts(decodeParts(snap.data))
        const current = writeParts(defaultProjectData(), draft.parts)
        const next = decodeProjectData(parseJson(json))
        const revision = draft.revision + 1
        const partRevisions = { ...draft.partRevisions }
        for (const part of PARTS) if (!partEquals(part, current, next)) partRevisions[part] = revision
        db.prepare(
          `UPDATE drafts SET data = ?, revision = ?, part_revisions = ?, last_changed_by = 'human', human_viewed_revision = ?,
             updated_at = ? WHERE id = ?`,
        ).run(json, revision, JSON.stringify(partRevisions), revision, now(), draftId)
        return { status: 'saved', draft: getDraft(draftId)! }
      })
    },

    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "Ended drafts in history"
    // Changes: Restore from an ended draft = a new open draft (the human's), forked now, carrying the snapshot's parts.
    restoreEndedDraftSnapshot(draftId, snapshotId) {
      return tx((): RestoreEndedResult => {
        const row = findDraftRow(draftId)
        const snap = db.prepare('SELECT data FROM snapshots WHERE id = ? AND draft_id = ?').get(snapshotId, draftId) as
          | { data: string }
          | undefined
        if (!row || !snap) return { status: 'missing' }
        if (row.state === 'open') return { status: 'open', draft: toDraft(row) }
        const label = `${limitText(row.label, LABEL_MAX - RESTORED_SUFFIX.length)}${RESTORED_SUFFIX}`
        const draft = insertDraft(row.project_id, label, 'human', decodeParts(snap.data))!
        return { status: 'saved', draft }
      })
    },

    deleteEndedDraft(draftId) {
      return tx((): DeleteEndedResult => {
        const row = findDraftRow(draftId)
        if (!row) return { status: 'missing' }
        if (row.state === 'open') return { status: 'open', draft: toDraft(row) }
        // Its snapshots go with it (draft_id cascades).
        db.prepare('DELETE FROM drafts WHERE id = ?').run(draftId)
        return { status: 'deleted' }
      })
    },
  }
}

const RESTORED_SUFFIX = ' (obnovený)'

// Production store: one lazily opened connection to TABLE_MAKER_DB (default data/table-maker.db).
let defaultStore: ProjectStore | undefined
export function projectStore(): ProjectStore {
  defaultStore ??= createProjectStore(openDatabase(process.env.TABLE_MAKER_DB ?? 'data/table-maker.db'))
  return defaultStore
}
